.darma-loader-darma-b15-dough-rise { --accent: var(--loader-color, #a16207); --accent-2: var(--loader-secondary-color, #fde68a); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .78); position: relative; }
.darma-loader-darma-b15-dough-rise .darma-loader-darma-b15-dough-rise__tin { position: absolute; left: 14%; right: 14%; bottom: 6%; height: 30%; border-radius: 4px 4px 10px 10px; background: linear-gradient(#94a3b8, #475569); }
.darma-loader-darma-b15-dough-rise .darma-loader-darma-b15-dough-rise__dough { position: absolute; left: 18%; right: 18%; bottom: 30%; height: 12%; border-radius: 46% 46% 12% 12% / 70% 70% 12% 12%; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent-2)), var(--accent)); animation: darma-loader-darma-b15-dough-rise-dough-proof calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b15-dough-rise i { position: absolute; width: 6%; height: 6%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: darma-loader-darma-b15-dough-rise-dough-flour calc(var(--loader-speed, 1s) * 3) ease-out infinite; }
.darma-loader-darma-b15-dough-rise i:nth-of-type(1) { left: 24%; bottom: 60%; }
.darma-loader-darma-b15-dough-rise i:nth-of-type(2) { left: 50%; bottom: 68%; animation-delay: calc(var(--loader-speed, 1s) * 1); }
.darma-loader-darma-b15-dough-rise i:nth-of-type(3) { left: 72%; bottom: 62%; animation-delay: calc(var(--loader-speed, 1s) * 2); }
@keyframes darma-loader-darma-b15-dough-rise-dough-proof { 0%, 8% { height: 12%; } 60%, 82% { height: 46%; } 98%, 100% { height: 12%; } }
@keyframes darma-loader-darma-b15-dough-rise-dough-flour { 0% { opacity: 0; transform: translateY(40%) scale(.5); } 25% { opacity: .8; } 100% { opacity: 0; transform: translateY(-70%) scale(1.2); } }

